-- A representative standard unit plus structured printable notebook handouts.
alter table public.lesson_records
  add column if not exists notebook_pages jsonb not null default '[]'::jsonb
  check (jsonb_typeof(notebook_pages) = 'array');

on conflict (lesson_code) do update set title=excluded.title,unit_name=excluded.unit_name,chapter_name=excluded.chapter_name,sort_order=excluded.sort_order,mission_position=excluded.mission_position,presentation_url=excluded.presentation_url,guide_url=excluded.guide_url,updated_at=now();
